/**
 * Venafi TLS Protect Datacenter Node - Version 1
 * Discriminator: resource=certificate, operation=download
 */


interface Credentials {
  venafiTlsProtectDatacenterApi: CredentialReference;
}

/** Download a certificate */
export type VenafiTlsProtectDatacenterV1CertificateDownloadParams = {
  resource: 'certificate';
  operation: 'download';
/**
 * Certificate DN
 */
    certificateDn: string | Expression<string>;
/**
 * Include Private Key
 * @default false
 */
    includePrivateKey?: boolean | Expression<boolean>;
/**
 * Password
 * @displayOptions.show { includePrivateKey: [true] }
 * @required when the displayOptions conditions above match
 */
    password?: string | Expression<string>;
/**
 * The name of the input field containing the binary file data to be uploaded
 * @default data
 */
    binaryProperty?: string | Expression<string>;
/**
 * Additional Fields
 * @default {}
 */
    additionalFields?: {
    /** Include Chain
     * @default true
     */
    IncludeChain?: boolean | Expression<boolean>;
    /** Root First Order
     */
    RootFirstOrder?: string | Expression<string>;
    /** Keystore Password
     */
    KeystorePassword?: string | Expression<string>;
  };
};

export type VenafiTlsProtectDatacenterV1CertificateDownloadNode = {
  type: 'n8n-nodes-base.venafiTlsProtectDatacenter';
  version: 1;
  config: NodeConfig<VenafiTlsProtectDatacenterV1CertificateDownloadParams> & { credentials?: Credentials };
};